create or replace view public.provider_health_intelligence_queue as select r.organization_id,r.vendor_id,r.id provider_relationship_id,r.legal_entity_id,r.legal_entity_code,r.vendor_code,h.health_score,h.health_state,h.hard_blocker,h.blocker_codes,h.evaluated_at,s.open_case_count,s.case_attention_count,s.needs_reply_count,s.pending_approval_count,s.document_attention_count,s.compliance_status,s.required_integration_count,s.ready_integration_count,r.primary_blocker from public.provider_relationships r left join public.provider_health_latest h on h.organization_id=r.organization_id and h.provider_relationship_id=r.id left join public.provider_service_360_relationship_summary s on s.organization_id=r.organization_id and s.provider_relationship_id=r.id where r.lifecycle_status not in ('offboarded','archived');
revoke all on table public.provider_health_intelligence_queue from public,anon,authenticated,service_role;
grant select on table public.provider_health_intelligence_queue to service_role;
